    reg [7:0] neighbor_count;

    // Function to compute the number of live neighbors for a given cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % 16;
                    int c = (col + j) % 16;
                    if (current_q[(r * 16) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute next state
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            for (int i = 0; i < 16; i = i + 1) begin
                for (int j = 0; j < 16; j = j + 1) begin
                    int r = i;
                    int c = j;
                    neighbor_count = count_neighbors(r, c);
                    if (neighbor_count < 2) begin
                        next_q[(r * 16) + c] <= 1'b0;
                    end else if (neighbor_count == 2) begin
                        next_q[(r * 16) + c] <= current_q[(r * 16) + c];
                    end else if (neighbor_count == 3) begin
                        next_q[(r * 16) + c] <= 1'b1;
                    end else begin
                        next_q[(r * 16) + c] <= 1'b0;
