module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State machine states
    typedef enum reg [2:0] {
        STATE_LOW,      // Below s[0]
        STATE_MIDDLE1,  // Between s[1] and s[0]
        STATE_MIDDLE2,  // Between s[2] and s[1]
        STATE_HIGH      // Above s[2]
    } state_t;

    state_t current_state, next_state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
            current_state <= STATE_LOW;
            prev_s <= 3'b000;
        end else begin
            // Update state
            current_state <= next_state;

            // Update previous sensor state
            prev_s <= s;

            // Determine outputs based on current state and previous sensor state
            case (current_state)
                STATE_LOW: begin
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                end
                STATE_MIDDLE1: begin
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                STATE_MIDDLE2: begin
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                STATE_HIGH: begin
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
            endcase
        end
    end

    // Next state logic
    always @(s, current_state, prev_s) begin
        next_state = current_state;

        // Determine next state based on current sensor input
        if (s == 3'b111) begin
            next_state = STATE_HIGH;
        end else if (s == 3'b110) begin
            next_state = STATE_MIDDLE2;
        end else if (s == 3'b100) begin
            next_state = STATE_MIDDLE1;
        end else if (s == 3'b000) begin
            next_state = STATE_LOW;
        end
    end

endmodule

